#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;
    // Reachable balances ('(' minus ')') form a step-2 interval [low, high];
    // every reachable state keeps the same number of surviving parentheses.
    long long survivors = 0, low = 0, high = 0;
    for (char ch : s) {
        if (ch == '(') { survivors++; low++; high++; }
        else if (ch == ')') { survivors++; low--; high--; }
        else {
            long long removed = min<long long>(ch - '0', survivors); // a digit larger than the count removes all
            if (removed == 0) continue;
            low = max(removed - survivors, low - removed);
            high = min(survivors - removed, high + removed);
            survivors -= removed;
        }
    }
    cout << (survivors % 2 == 0 && low <= 0 && 0 <= high ? 1 : 0) << "\n";
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        // Reachable balances ('(' minus ')') form a step-2 interval [low, high];
        // every reachable state keeps the same number of surviving parentheses.
        long survivors = 0, low = 0, high = 0;
        int c;
        while ((c = in.read()) != -1) {
            if (c == '(') { survivors++; low++; high++; }
            else if (c == ')') { survivors++; low--; high--; }
            else if (c >= '0' && c <= '9') {
                long removed = Math.min(c - '0', survivors); // a digit larger than the count removes all
                if (removed == 0) continue;
                low = Math.max(removed - survivors, low - removed);
                high = Math.min(survivors - removed, high + removed);
                survivors -= removed;
            }
        }
        System.out.println(survivors % 2 == 0 && low <= 0 && 0 <= high ? 1 : 0);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<20)
	line, _ := reader.ReadString('\n')
	s := strings.TrimSpace(line)
	// Reachable balances ('(' minus ')') form a step-2 interval [low, high];
	// every reachable state keeps the same number of surviving parentheses.
	survivors, low, high := 0, 0, 0
	for i := 0; i < len(s); i++ {
		switch ch := s[i]; {
		case ch == '(':
			survivors++
			low++
			high++
		case ch == ')':
			survivors++
			low--
			high--
		default:
			removed := min(int(ch-'0'), survivors) // a digit larger than the count removes all
			if removed == 0 {
				continue
			}
			low = max(removed-survivors, low-removed)
			high = min(survivors-removed, high+removed)
			survivors -= removed
		}
	}
	if survivors%2 == 0 && low <= 0 && 0 <= high {
		fmt.Println(1)
	} else {
		fmt.Println(0)
	}
}
